$root=dirname(__DIR__);$mediaRoot=$root.'/media';$imagesDir=$mediaRoot.'/images';$videosDir=$mediaRoot.'/videos';$notice='';$error='';
foreach([$mediaRoot,$imagesDir,$videosDir] as $dir){if(!is_dir($dir)&&!@mkdir($dir,0755,true)&&!is_dir($dir))$error='Media katalogini yaratib bo‘lmadi.';}
function e(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
function humanSize(int $bytes):string{if($bytes<1024)return $bytes.' B';if($bytes<1048576)return number_format($bytes/1024,1).' KB';return number_format($bytes/1048576,1).' MB';}
function mediaFiles(string $dir,string $type):array{$allowed=$type==='image'?['jpg','jpeg','png','webp','gif','avif']:['mp4','webm','mov'];if(!is_dir($dir))return []; $items=[];foreach(scandir($dir)?:[] as $name){if($name==='.'||$name==='..')continue;$path=$dir.DIRECTORY_SEPARATOR.$name;if(!is_file($path))continue;$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(!in_array($ext,$allowed,true))continue;$items[]=['name'=>$name,'path'=>'media/'.($type==='image'?'images/':'videos/').$name,'size'=>(int)filesize($path),'mtime'=>(int)filemtime($path),'type'=>$type];}usort($items,fn(array $a,array $b)=>$b['mtime']<=>$a['mtime']);return $items;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!adminVerifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('CSRF token noto‘g‘ri yoki sessiya eskirgan.');$action=(string)($_POST['action']??'');if($action==='upload'){if(!isset($_FILES['media'])||!is_array($_FILES['media']))throw new RuntimeException('Fayl tanlanmagan.');$upload=$_FILES['media'];if(($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Upload amalga oshmadi.');$original=(string)($upload['name']??'');$tmp=(string)($upload['tmp_name']??'');$size=(int)($upload['size']??0);if($size<=0||$size>25*1024*1024)throw new RuntimeException('Fayl hajmi 1–25 MB oralig‘ida bo‘lishi kerak.');$ext=strtolower(pathinfo($original,PATHINFO_EXTENSION));$images=['jpg','jpeg','png','webp','gif','avif'];$videos=['mp4','webm','mov'];$kind=in_array($ext,$images,true)?'image':(in_array($ext,$videos,true)?'video':'');if($kind==='')throw new RuntimeException('Faqat JPG, PNG, WEBP, GIF, AVIF, MP4, WEBM yoki MOV qabul qilinadi.');if(!is_uploaded_file($tmp))throw new RuntimeException('Upload manbasi tasdiqlanmadi.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$allowedMime=$kind==='image'?['image/jpeg','image/png','image/webp','image/gif','image/avif']:['video/mp4','video/webm','video/quicktime'];if(!in_array($mime,$allowedMime,true))throw new RuntimeException('Fayl MIME turi extension bilan mos emas.');$safe=preg_replace('/[^a-zA-Z0-9._-]+/','-',pathinfo($original,PATHINFO_FILENAME));$safe=trim((string)$safe,'-_.');if($safe==='')$safe='media';$safe.='-'.date('Ymd-His').'-'.bin2hex(random_bytes(3)).'.'.$ext;$target=($kind==='image'?$imagesDir:$videosDir).DIRECTORY_SEPARATOR.$safe;if(!move_uploaded_file($tmp,$target))throw new RuntimeException('Faylni media katalogiga ko‘chirish amalga oshmadi.');$notice='Media muvaffaqiyatli yuklandi: '.$safe;}elseif($action==='delete'){$type=(string)($_POST['type']??'');$name=basename((string)($_POST['name']??''));$dir=$type==='image'?$imagesDir:($type==='video'?$videosDir:'');$allowed=$type==='image'?['jpg','jpeg','png','webp','gif','avif']:['mp4','webm','mov'];$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));if($dir===''||$name===''||!in_array($ext,$allowed,true))throw new RuntimeException('Media identifikatori noto‘g‘ri.');$target=$dir.DIRECTORY_SEPARATOR.$name;if(!is_file($target)||!unlink($target))throw new RuntimeException('Media o‘chirilmadi.');$notice='Media o‘chirildi: '.$name;}else{throw new RuntimeException('Noma’lum amal.');}}catch(Throwable $exception){$error=$exception->getMessage();}}
$images=mediaFiles($imagesDir,'image');$videos=mediaFiles($videosDir,'video');
