order:0;background:var(--navy);color:#fff;padding:16px 24px;cursor:pointer;font:inherit;font-size:11px;font-weight:850;letter-spacing:.06em}.button:hover{background:#1d3154}.section{margin-top:55px}.section-head{display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid var(--line);padding-bottom:15px;margin-bottom:22px}.section-head h2{margin:0;font-size:17px}.count{color:var(--muted);font-size:10px;letter-spacing:.12em;text-transform:uppercase}.gallery{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.asset{background:var(--paper);overflow:hidden;border:1px solid var(--line)}.preview{aspect-ratio:4/3;background:#e9e9e5;display:block;width:100%;object-fit:cover}.asset-info{padding:15px}.name{font-size:11px;font-weight:750;word-break:break-word;line-height:1.45}.meta{margin-top:6px;color:var(--muted);font-size:9px}.delete{margin-top:13px;border:1px solid var(--line);background:transparent;padding:9px 11px;cursor:pointer;color:#8b3f36;font:inherit;font-size:9px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.empty{padding:30px 0;color:var(--muted);font-size:12px;border-bottom:1px solid var(--line)}@media(max-width:900px){.gallery{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.shell{width:min(100% - 26px,600px)}main{padding:48px 0 70px}.heading{display:block}.heading p{margin-top:24px}.upload{padding:24px}.upload-row{display:block}.button{width:100%;margin-top:15px}.gallery{grid-template-columns:repeat(2,1fr)}}@media(max-width:420px){.gallery{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}</style></head><body><div class="shell"><header class="top"><div class="brand">CHIMYON / ADMIN</div><a class="back" href="index.php">← Control center</a></header><main><section class="heading"><div><p class="eyebrow">09 / MEDIA LIBRARY</p><h1>Media.</h1></div><p>Saytning vizual manbalarini markaziy katalogdan boshqaring. Upload MIME orqali tekshiriladi va media katalogidan tashqariga yozilmaydi.</p></section><?php if($notice):?><div class="notice" role="status"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="error" role="alert"><?=e($error)?></div><?php endif;?><form class="upload" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(adminCsrfToken())?>"><input type="hidden" name="action" value="upload"><div class="upload-row"><div class="field"><label for="media">Upload media</label><input id="media" name="media" type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif,video/mp4,video/webm,video/quicktime" required><small>JPG · PNG · WEBP · GIF · AVIF · MP4 · WEBM · MOV · maximum 25 MB.</small></div><button class="button" type="submit">UPLOAD →</button></div></form><section class="section"><div class="section-head"><h2>Images</h2><span class="count"><?=count($images)?> assets</span></div><?php if(!$images):?><div class="empty">Hozircha image media mavjud emas.</div><?php else:?><div class="gallery"><?php foreach($images as $item):?><article class="asset"><img class="preview" src="<?=e($item['path'])?>" alt="<?=e($item['name'])?>" loading="lazy"><div class="asset-info"><div class="name"><?=e($item['name'])?></div><div class="meta"><?=e(humanSize($item['size']))?></div><form method="post" onsubmit="return confirm('Ushbu media faylini o‘chirishni tasdiqlaysizmi?')"><input type="hidden" name="csrf" value="<?=e(adminCsrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="type" value="image"><input type="hidden" name="name" value="<?=e($item['name'])?>"><button class="delete" type="submit">Delete</button></form></div></article><?php endforeach;?></div><?php endif;?></section><section class="section"><div class="section-head"><h2>Videos</h2><span class="count"><?=count($videos)?> assets</span></div><?php if(!$videos):?><div class="empty">Hozircha video media mavjud emas.</div><?php else:?><div class="gallery"><?php foreach($videos as $item):?><article class="asset"><video class="preview" src="<?=e($item['path'])?>" controls preload="metadata"></video><div class="asset-info"><div class="name"><?=e($item['name'])?></div><div class="meta"><?=e(humanSize($item['size']))?></div><form method="post" onsubmit="return confirm('Ushbu media faylini o‘chirishni tasdiqlaysizmi?')"><input type="hidden" name="csrf" value="<?=e(adminCsrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="type" value="video"><input type="hidden" name="name" value="<?=e($item['name'])?>"><button class="delete" type="submit">Delete</button></form></div></article><?php endforeach;?></div><?php endif;?></section></main></div></body></html>